/**
 * @summary List documents for student
 */
export const getListDocumentsUrl = (
  studentId: number,
  params?: ListDocumentsParams,
) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? "null" : value.toString());
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0
    ? `/api/students/${studentId}/documents?${stringifiedParams}`
    : `/api/students/${studentId}/documents`;
};

export const listDocuments = async (
  studentId: number,
  params?: ListDocumentsParams,
  options?: RequestInit,
): Promise<Document[]> => {
  return customFetch<Document[]>(getListDocumentsUrl(studentId, params), {
    ...options,
    method: "GET",
  });
};

